  if (!result.success) {
    const lines = [configPath]
    for (const issue of result.error.issues) {
      const dotted = issue.path.join('.')
      lines.push(`${dotted}: ${issue.message}`)
    }
    throw new ConfigError('invalid', lines)
  }
  return result.data
}

